menu.event:

component:E("FadedBG").onDoneHide = function(e)
	component:root():removePopUp(component:name())
end

component:E("Dialog").onAllDialogsCompleted = function(e)
	game.getLocalSettings():set("dipster_rock_tutorial", "true")
	component:E("FadedBG"):Hide()
end

component:E("Dialog"):SetDialogs({
	{
		Avatar = "gfx/menu/minigames/minigame_alcordion_04",
		Dialog = "DIPSTER_TUT_ROCK_DIALOG_1"
	},
	{
		Avatar = "gfx/menu/minigames/minigame_alcordion_02",
		Dialog = "DIPSTER_TUT_ROCK_DIALOG_2"
	}
})
